{
  "summary": "Determine the number of months Acme missed its uptime SLA this contract year and the total service credit owed, then report to the CFO.",
  "reply_type": "internal_answer",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "Locate the Acme contract and SLA policy documents to determine uptime SLA thresholds, then read monthly performance/uptime reports for the current contract year to identify each month Acme fell below the SLA. Use the 'SLA credit calculator' tool with these performance figures and the contract's credit terms to compute the exact number of missed months and total service credit owed. If any amounts are in a foreign currency (e.g., USD), use the 'Currency converter (live)' tool to convert to the reporting currency.",
      "why": "The retriever must gather all contract terms, SLA thresholds, and monthly performance data, then use the SLA credit calculator to produce the exact miss count and credit owed, converting currency if needed."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Compose a concise internal answer to the CFO stating the number of months Acme missed its uptime SLA this contract year and the total service credit owed, citing the underlying figures from the retriever's findings.",
      "why": "The executor synthesizes the gathered facts into a clear final answer for the CFO."
    }
  ],
  "escalate": null
}
